INSERT INTO "Post" ("id", "slug", "kicker", "title", "lead", "body", "homeImageId", "homeImageAlt", "innerImageId", "innerImageAlt", "videoType", "videoUrl", "videoDuration", "categoryId", "status", "publishedAt", "hasOwnPage", "views", "metaTitle", "metaDescription", "metaKeywords", "ogImageId", "canonicalUrl", "createdAt", "updatedAt") VALUES ('cms91w7ps000hute8wed7adcg', 'بیمه-مرکزی-سهم-صنعت-بیمه-از-تولید-ناخالص-داخلی-باید-به-۵-درصد-برسد', NULL, 'بیمه مرکزی: سهم صنعت بیمه از تولید ناخالص داخلی باید به ۵ درصد برسد', 'رئیس کل بیمه مرکزی در نشست هم‌اندیشی مدیران صنعت بیمه از تدوین سند توسعه صنعت بیمه خبر داد و گفت: بر اساس این سند، ضریب نفوذ بیمه و سهم صنعت از تولید ناخالص داخلی تا پایان برنامه هفتم به ۵ درصد می‌رسد.', '<p>رئیس کل بیمه مرکزی در نشست هم‌اندیشی مدیران صنعت بیمه از تدوین سند توسعه صنعت بیمه خبر داد و گفت: بر اساس این سند، ضریب نفوذ بیمه و سهم صنعت از تولید ناخالص داخلی تا پایان برنامه هفتم به ۵ درصد می‌رسد.</p><p>گزارش کامل این خبر را در ادامه می‌خوانید. این متن برای نمایش نمونه‌ای بدنه خبر در نسخه آزمایشی تولید شده است و توسط تحریریه بیمه نیوز جایگزین خواهد شد.</p>', 'cms91w7pq000fute8i21jkd9m', 'بیمه مرکزی: سهم صنعت بیمه از تولید ناخالص داخلی باید به ۵ درصد برسد', NULL, '', 'NONE', NULL, NULL, 'cms903b8i0001utv8pydzjonx', 'PUBLISHED', '2026-07-31T14:11:33.633Z', TRUE, 0, 'بیمه مرکزی: سهم صنعت بیمه از تولید ناخالص داخلی باید به ۵ درصد برسد', 'رئیس کل بیمه مرکزی در نشست هم‌اندیشی مدیران صنعت بیمه از تدوین سند توسعه صنعت بیمه خبر داد و گفت: بر اساس این سند، ضریب نفوذ بیمه و سهم صنعت از تولید ناخالص داخلی تا پایان برنامه هفتم به ۵ درصد می‌رسد.', NULL, NULL, NULL, '2026-07-31T14:41:33.712Z', '2026-08-18T16:48:57.159Z') ON CONFLICT DO NOTHING;
